// ===== 바꿀 값은 이 노드에만 있습니다 =====
// trust: 매체 기본 신뢰도(1~5), grade: 출처 등급(공시/통신사/해설/커뮤니티)
return [{
  json: {
    supabaseUrl: 'https://YOUR-PROJECT.supabase.co', // Supabase → Project Settings → API의 Project URL

    collectHours: 48, // 이보다 오래된 기사는 모으지 않음
    perSourceMax: 15, // 한 번 실행에 피드(검색어)당 최대 기사 수
    totalMax: 120, // 한 번 실행에 전체 최대 기사 수

    // 관심 종목(Supabase watchlist) 뉴스: 국내는 네이버, 미국은 Google News에서 종목마다 검색
    watchNewsMax: 20, // 검색할 관심 종목 최대 수
    watchNaverDisplay: 10, // 국내 관심 종목 1개당 네이버 검색 결과 수

    // 1) 매체 RSS
    feeds: [
      { name: '연합뉴스 경제', source: '연합뉴스', url: 'https://www.yna.co.kr/rss/economy.xml', market: 'KR', trust: 4, grade: '통신사' },
      { name: '한국경제 증권', source: '한국경제', url: 'https://www.hankyung.com/feed/finance', market: 'KR', trust: 4, grade: '해설' },
      { name: '매일경제 증권', source: '매일경제', url: 'https://www.mk.co.kr/rss/50200011/', market: 'KR', trust: 4, grade: '해설' },
      { name: 'CNBC Finance', source: 'CNBC', url: 'https://search.cnbc.com/rs/search/combinedcms/view.xml?partnerId=wrss01&id=10000664', market: 'US', trust: 4, grade: '해설' },
      { name: 'MarketWatch', source: 'MarketWatch', url: 'https://feeds.content.dowjones.io/public/rss/mw_topstories', market: 'US', trust: 4, grade: '해설' },
      { name: 'Yahoo Finance', source: 'Yahoo Finance', url: 'https://finance.yahoo.com/news/rssindex', market: 'US', trust: 3, grade: '해설' },
    ],

    // 2) Google News 검색 (최근 1일). 매체명은 기사마다 붙어 오며 아래 sources 표로 신뢰도를 정함
    googleNews: [
      { q: '코스피 OR 코스닥', market: 'KR' },
      { q: '금리 환율 증시', market: 'KR' },
      { q: 'stock market Wall Street', market: 'US' },
      { q: 'Federal Reserve rates', market: 'US' },
      { q: 'site:reuters.com markets', market: 'US' },
    ],

    // 3) 네이버 뉴스 검색 API (자격 증명 "Naver API"가 필요). 비우면 건너뜀
    naverQueries: ['코스피', '코스닥', '증시', '환율', '금리'],
    naverDisplay: 30,
    // 네이버 원문 주소의 도메인 → 매체명
    naverDomains: {
      'yna.co.kr': '연합뉴스', 'einfomax.co.kr': '연합인포맥스', 'hankyung.com': '한국경제', 'mk.co.kr': '매일경제',
      'sedaily.com': '서울경제', 'edaily.co.kr': '이데일리', 'mt.co.kr': '머니투데이', 'news.mt.co.kr': '머니투데이',
      'fnnews.com': '파이낸셜뉴스', 'asiae.co.kr': '아시아경제', 'heraldcorp.com': '헤럴드경제', 'biz.chosun.com': '조선비즈',
      'chosun.com': '조선일보', 'joongang.co.kr': '중앙일보', 'donga.com': '동아일보', 'hani.co.kr': '한겨레', 'khan.co.kr': '경향신문',
      'news1.kr': '뉴스1', 'newsis.com': '뉴시스', 'thebell.co.kr': '더벨', 'bloter.net': '블로터', 'ytn.co.kr': 'YTN', 'yonhapnewstv.co.kr': '연합뉴스TV',
    },

    // 매체명 → 신뢰도·등급 (Google News, 네이버 공통). 목록에 없는 매체는 unknownSource 값
    sources: {
      '연합뉴스': [4, '통신사'], '연합인포맥스': [5, '통신사'], '뉴스1': [3, '통신사'], '뉴시스': [3, '통신사'],
      '한국경제': [4, '해설'], '매일경제': [4, '해설'], '서울경제': [3, '해설'], '이데일리': [3, '해설'], '머니투데이': [3, '해설'],
      '파이낸셜뉴스': [3, '해설'], '아시아경제': [3, '해설'], '헤럴드경제': [3, '해설'], '조선비즈': [3, '해설'], '더벨': [4, '해설'],
      '조선일보': [4, '해설'], '중앙일보': [4, '해설'], '동아일보': [4, '해설'], '한겨레': [4, '해설'], '경향신문': [4, '해설'],
      'Reuters': [5, '통신사'], 'Associated Press': [5, '통신사'], 'AP News': [5, '통신사'], 'Bloomberg': [5, '통신사'], 'Bloomberg.com': [5, '통신사'],
      'The Wall Street Journal': [5, '해설'], 'Financial Times': [5, '해설'], 'CNBC': [4, '해설'], 'MarketWatch': [4, '해설'],
      'Barron\'s': [4, '해설'], 'Yahoo Finance': [3, '해설'], 'Investopedia': [3, '해설'], 'Seeking Alpha': [2, '커뮤니티'], 'The Motley Fool': [2, '커뮤니티'],
    },
    unknownSource: [2, '해설'],
  },
}];

// 매체 RSS와 Google News 검색 주소를 요청 목록으로 만듭니다.
const c = $('설정').first().json;
const out = [];
for (const f of c.feeds) {
  out.push({ json: { kind: 'rss', label: f.name, url: f.url, source: f.source, market: f.market, trust: f.trust, grade: f.grade } });
}
for (const g of c.googleNews) {
  const q = encodeURIComponent(`${g.q} when:1d`);
  const loc = g.market === 'KR' ? 'hl=ko&gl=KR&ceid=KR:ko' : 'hl=en-US&gl=US&ceid=US:en';
  out.push({ json: { kind: 'gnews', label: `Google News: ${g.q}`, url: `https://news.google.com/rss/search?q=${q}&${loc}`, market: g.market } });
}
// 관심 종목 중 미국 종목: Google News 영어 검색
const watch = (($('관심 종목 조회').first().json || {}).watchlist || []).slice(0, c.watchNewsMax);
for (const w of watch) {
  if (w.market !== 'US') continue;
  const q = encodeURIComponent(`${w.code} stock when:1d`);
  out.push({ json: { kind: 'gnews', label: `관심 종목: ${w.code}`, url: `https://news.google.com/rss/search?q=${q}&hl=en-US&gl=US&ceid=US:en`, market: 'US', ticker: { market: 'US', code: w.code, name: w.label || w.name } } });
}
return out;

// 네이버 뉴스 검색 요청 (일반 검색어 + 국내 관심 종목). 둘 다 없으면 건너뛰기 표시가 붙은 요청 1개만 보냅니다.
const c = $('설정').first().json;
const watch = (($('관심 종목 조회').first().json || {}).watchlist || []).slice(0, c.watchNewsMax).filter((w) => w.market === 'KR');
const reqs = (c.naverQueries || []).map((q) => ({ q, display: c.naverDisplay || 30 }));
for (const w of watch) reqs.push({ q: w.label || w.name, display: c.watchNaverDisplay || 10, ticker: { market: 'KR', code: w.code, name: w.label || w.name } });
if (!reqs.length) {
  return [{ json: { skip: true, url: 'https://openapi.naver.com/v1/search/news.json?query=skip&display=1' } }];
}
return reqs.map((r) => ({
  json: {
    kind: 'naver',
    label: r.ticker ? `관심 종목: ${r.q}` : `네이버: ${r.q}`,
    query: r.q,
    ticker: r.ticker,
    url: `https://openapi.naver.com/v1/search/news.json?query=${encodeURIComponent(r.q)}&display=${r.display}&sort=date`,
  },
}));

// RSS·Atom·네이버 응답을 읽어 기사 후보로 정리합니다.
// n8n Code 노드 실행 환경에는 URL, Buffer가 없을 수 있어 모두 문자열로 처리합니다.
const c = $('설정').first().json;
const now = Date.now();
const since = now - c.collectHours * 3600_000;

// ---------- 도우미 ----------
const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', middot: '·', hellip: '…', lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', ndash: '–', mdash: '—' };
function decode(s) {
  if (!s) return '';
  return String(s)
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&([a-z]+);/gi, (m, n) => (NAMED[n.toLowerCase()] !== undefined ? NAMED[n.toLowerCase()] : m));
}
const strip = (s) => s.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const text = (s) => strip(decode(strip(decode(s))));
function tag(block, name) {
  const m = block.match(new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, 'i'));
  return m ? m[1] : '';
}
function linkOf(block) {
  let m = block.match(/<link[^>]*rel=["']alternate["'][^>]*href=["']([^"']+)["']/i) || block.match(/<link[^>]*href=["']([^"']+)["'][^>]*\/?>/i);
  if (m) return decode(m[1]).trim();
  const l = decode(tag(block, 'link')).trim();
  if (/^https?:\/\//i.test(l)) return l;
  const g = decode(tag(block, 'guid')).trim();
  return /^https?:\/\//i.test(g) ? g : '';
}
function hostOf(u) {
  const m = String(u).match(/^https?:\/\/([^/?#:]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '').replace(/^m\./, '') : '';
}
// 중복 비교용 키 (링크 자체는 원문 그대로 저장)
function urlKey(u) {
  let s = String(u).trim().replace(/^https?:\/\//i, '').replace(/#.*$/, '');
  let q = '';
  const qi = s.indexOf('?');
  if (qi >= 0) { q = s.slice(qi + 1); s = s.slice(0, qi); }
  const parts = s.split('/');
  const host = parts.shift().toLowerCase().replace(/^www\./, '').replace(/^m\./, '');
  const path = parts.join('/').replace(/\/+$/, '');
  const params = q.split('&').filter((p) => p && !/^(utm_|fbclid|gclid|ref=|from=|cmpid|ocid|rss=|feed=)/i.test(p)).sort();
  return host + '/' + path + (params.length ? '?' + params.join('&') : '');
}
function sourceInfo(name) {
  const v = c.sources[name] || c.unknownSource;
  return { trust: v[0], grade: v[1] };
}
function toIso(s) {
  const t = Date.parse(String(s).trim());
  return Number.isFinite(t) ? new Date(t).toISOString() : null;
}
function paired(item) {
  const p = item.pairedItem;
  if (Array.isArray(p)) return p[0] ? p[0].item : 0;
  return p && typeof p.item === 'number' ? p.item : 0;
}

const report = [];
const cands = [];
const push = (req, a) => {
  if (!a.url || !/^https?:\/\//i.test(a.url)) { req._r.bad++; return; }
  if (!a.published_at) { req._r.noDate++; return; }
  const t = Date.parse(a.published_at);
  if (t < since || t > now + 3600_000) { req._r.old++; return; }
  a.url_key = urlKey(a.url);
  a.tickers = req.ticker ? [req.ticker] : [];
  a.title = a.title.slice(0, 300);
  a.snippet = (a.snippet || '').slice(0, 500);
  cands.push(a);
  req._r.ok++;
};

// ---------- 1) RSS·Google News ----------
const rssReqs = $('요청 목록').all().map((i) => i.json);
for (const it of $('RSS 읽기').all()) {
  const req = rssReqs[paired(it)] || {};
  const r = { label: req.label || '?', status: '', ok: 0, old: 0, bad: 0, noDate: 0 };
  req._r = r;
  report.push(r);
  const j = it.json || {};
  const code = j.statusCode;
  const body = typeof j.body === 'string' ? j.body : typeof j.data === 'string' ? j.data : '';
  if (j.error || !code || code >= 400 || !body) {
    r.status = `실패 ${code || (j.error && (j.error.code || j.error.message)) || ''}`.trim();
    continue;
  }
  r.status = '성공';
  const blocks = body.match(/<item[\s>][\s\S]*?<\/item>/gi) || body.match(/<entry[\s>][\s\S]*?<\/entry>/gi) || [];
  const perSource = [];
  for (const b of blocks) {
    let title = text(tag(b, 'title'));
    if (!title) continue;
    const url = linkOf(b);
    const date = toIso(tag(b, 'pubDate') || tag(b, 'published') || tag(b, 'updated') || tag(b, 'dc:date'));
    const snippet = text(tag(b, 'description') || tag(b, 'summary') || tag(b, 'content'));
    let source = req.source, trust = req.trust, grade = req.grade;
    if (req.kind === 'gnews') {
      source = text(tag(b, 'source')) || 'Google News';
      if (title.endsWith(` - ${source}`)) title = title.slice(0, -(source.length + 3));
      ({ trust, grade } = sourceInfo(source));
    }
    perSource.push({ url, title, source, source_trust: trust, source_grade: grade, tier: 'T2', market: req.market, feed_kind: req.kind, published_at: date, snippet: req.kind === 'gnews' ? '' : snippet });
  }
  perSource.slice(0, 200).forEach((a) => push(req, a));
}

// ---------- 2) 네이버 ----------
const nvReqs = $('네이버 요청').all().map((i) => i.json);
for (const it of $('네이버 뉴스').all()) {
  const req = nvReqs[paired(it)] || {};
  if (req.skip) continue;
  const r = { label: req.label || '네이버', status: '', ok: 0, old: 0, bad: 0, noDate: 0 };
  req._r = r;
  report.push(r);
  const j = it.json || {};
  let body = j.body !== undefined ? j.body : j;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
  if (j.error || (j.statusCode && j.statusCode >= 400) || !body || !Array.isArray(body.items)) {
    r.status = `실패 ${j.statusCode || (j.error && j.error.message) || ''}`.trim();
    continue;
  }
  r.status = '성공';
  for (const n of body.items) {
    const url = (n.originallink || n.link || '').trim();
    const host = hostOf(url);
    const source = c.naverDomains[host] || c.naverDomains[host.split('.').slice(-3).join('.')] || c.naverDomains[host.split('.').slice(-2).join('.')] || host;
    const { trust, grade } = sourceInfo(source);
    push(req, { url, title: text(n.title), source, source_trust: trust, source_grade: grade, tier: 'T2', market: 'KR', feed_kind: 'naver', published_at: toIso(n.pubDate), snippet: text(n.description) });
  }
}

const okFeeds = report.filter((r) => r.status === '성공').length;
if (report.length && okFeeds === 0) {
  throw new Error('모든 피드 요청이 실패했습니다.\n' + report.map((r) => `${r.label}: ${r.status}`).join('\n'));
}

// 같은 실행 안의 중복 제거 (신뢰도 높은 매체 우선)
const KIND = { rss: 0, naver: 1, gnews: 2 }; // 같은 기사면 매체 RSS의 제목·요약을 우선
cands.sort((a, b) => b.source_trust - a.source_trust || KIND[a.feed_kind] - KIND[b.feed_kind] || b.published_at.localeCompare(a.published_at));
const seen = new Set();
const uniq = [];
const byKey = {};
for (const a of cands) {
  const kept = byKey[a.url_key];
  if (kept) { // 같은 기사: 관심 종목 표시만 합침
    for (const t of a.tickers) if (!kept.tickers.some((x) => x.code === t.code)) kept.tickers.push(t);
    continue;
  }
  byKey[a.url_key] = a;
  uniq.push(a);
}

if (!uniq.length) return []; // 새 기사 없음: 정상, 여기서 조용히 끝남
return [{ json: { candidates: uniq, keys: uniq.map((a) => a.url_key), report } }];

// 이미 저장된 기사를 빼고, 피드당·전체 한도를 적용합니다.
const c = $('설정').first().json;
const { candidates } = $('기사 정리').first().json;
const res = $input.first().json || {};
const existing = new Set(Array.isArray(res.keys) ? res.keys : []);

const fresh = candidates.filter((a) => !existing.has(a.url_key));
fresh.sort((a, b) => b.published_at.localeCompare(a.published_at));

const per = {};
const picked = [];
for (const a of fresh) {
  const k = `${a.feed_kind}:${a.source}`;
  per[k] = (per[k] || 0) + 1;
  if (per[k] > c.perSourceMax) continue;
  picked.push(a);
  if (picked.length >= c.totalMax) break;
}
if (!picked.length) return [];
return picked.map((a) => ({ json: a }));

// "링크 확인" 결과로 열리지 않는 기사를 빼고 저장할 행을 만듭니다.
// 404·410·5xx·연결 실패는 제외, 봇 차단(401·403·405·429)은 브라우저에서 열리므로 유지
function paired(item) {
  const p = item.pairedItem;
  if (Array.isArray(p)) return p[0] ? p[0].item : 0;
  return p && typeof p.item === 'number' ? p.item : 0;
}
const arts = $('새 기사 고르기').all().map((i) => i.json);
const rows = [];
const dead = [];
for (const it of $input.all()) {
  const a = arts[paired(it)];
  if (!a) continue;
  const j = it.json || {};
  const code = j.statusCode;
  const bad = j.error || !code || code === 404 || code === 410 || code >= 500;
  if (bad) { dead.push({ url: a.url, status: code || 'error' }); continue; }
  rows.push({
    url_key: a.url_key, url: a.url, title: a.title, source: a.source, source_trust: a.source_trust,
    source_grade: a.source_grade, tier: a.tier, market: a.market, feed_kind: a.feed_kind,
    published_at: a.published_at, snippet: a.snippet, tickers: a.tickers || [], status: 'new',
  });
}
if (!rows.length) return [];
return [{ json: { rows, dead } }];
